def lum(c):
    c=c/255
    return c/12.92 if c<=0.04045 else ((c+0.055)/1.055)**2.4
def L(hexs):
    h=hexs.lstrip('#'); r,g,b=(int(h[i:i+2],16) for i in (0,2,4))
    return 0.2126*lum(r)+0.7152*lum(g)+0.0722*lum(b)
def cr(a,b):
    la,lb=L(a),L(b); hi,lo=max(la,lb),min(la,lb)
    return (hi+0.05)/(lo+0.05)
for fg,bg in [('#6B7280','#FFFFFF'),('#6B7280','#F6F7FA'),('#6B7280','#EBEBED'),('#1A3A8C','#E8EFFF'),('#FFFFFF','#EBEBED'),('#9CA3AF','#FFFFFF'),('#FFFFFF','#2563EB'),('#60A5FA','#111827'),('#F9FAFB','#111827')]:
