            c = core.arenaAlloc(handle, ((String) value).getBytes(StandardCharsets.UTF_8));
        } else {
            c = ValueEncoder.encodeBits(valueType, value);
        }
        push(Categories.PARAMETER, Commands.Parameter.SET_DESIGN_TOKEN, 0, pathRef, valueType, c);
